before:
if let Some(manifest) = manifest {
    self.extraction_records = Some(
        crate::manifest_records::save(
            dir,
            manifest,
            &previous.data_dir,
            previous.extraction_records.as_ref(),
        )
        .map_err(store_io)?,
    );
    self.inject("after_extraction_persist")?;
    sidecar::save_manifest(dir, &manifest.header()).map_err(store_io)?;
}

after:
if let Some(manifest) = manifest {
    sidecar::save_manifest(dir, manifest).map_err(store_io)?;
    self.extraction_records = None;
}
